export function getMockRoast(name: string, friendName: string | undefined, style: RoastStyle): RoastResponse {
  const db = ROAST_DATABASE[style] || ROAST_DATABASE[RoastStyle.FUNNY];
  
  // filter templates that match friendName requirement if possible
  const validTemplates = db.templates.filter(t => {
    if (friendName) {
      return t.includes("{friendName}");
    } else {
      return !t.includes("{friendName}");
    }
  });

  const templatesToUse = validTemplates.length > 0 ? validTemplates : db.templates;
  const rawTemplate = templatesToUse[Math.floor(Math.random() * templatesToUse.length)];
  
  const roast = rawTemplate
    .replace(/{name}/g, name || "Umar")
    .replace(/{friendName}/g, friendName || "their bestie");

  const emoji = db.emojis[Math.floor(Math.random() * db.emojis.length)];
  const avatar = db.avatars[Math.floor(Math.random() * db.avatars.length)];
  const punchline = db.punchlines[Math.floor(Math.random() * db.punchlines.length)];
  const vibeScore = Math.floor(Math.random() * 41) + 60; // 60 to 100

  return {
    roast,
    style,
    emoji,
    avatar,
    vibeScore,
    punchline
  };
}
